import React, { useState } from 'react';
import { BarChart2, AlertTriangle, Lightbulb, Settings, Home, FileText, CheckCircle2, DollarSign, Users, ChevronDown } from 'lucide-react';

// --- Mock Data --- //
const forecastData = {
  initial: [
    { week: 'This Week', balance: 185230, change: 15200 },
    { week: 'Week 2', balance: 142100, change: -43130 },
    { week: 'Week 3', balance: 98450, change: -43650 },
    { week: 'Week 4', balance: 47250, change: -51200 },
    { week: 'Week 5', balance: -15400, change: -62650, shortfall: true },
    { week: 'Week 6', balance: 28900, change: 44300 },
    { week: 'Week 7', balance: 75600, change: 46700 },
    { week: 'Week 8', balance: 110300, change: 34700 },
  ],
  resolved: [
    { week: 'This Week', balance: 185230, change: 15200 },
    { week: 'Week 2', balance: 142100, change: -43130 },
    { week: 'Week 3', balance: 98450, change: -43650 },
    { week: 'Week 4', balance: 47250, change: -51200 },
    { week: 'Week 5', balance: 34600, change: -12650 },
    { week: 'Week 6', balance: 78900, change: 44300 },
    { week: 'Week 7', balance: 125600, change: 46700 },
    { week: 'Week 8', balance: 160300, change: 34700 },
  ]
};

const shortfallDetails = [
  { type: 'Outgoing', description: 'Supplier Payment - Global Logistics', amount: -35000, date: 'in 25 days' },
  { type: 'Outgoing', description: 'ATO BAS Payment', amount: -28500, date: 'in 26 days' },
  { type: 'Incoming (Delayed)', description: 'Customer Invoice #INV-1882', amount: 22000, date: 'Expected in 32 days' },
  { type: 'Outgoing', description: 'Payroll Run - Fortnightly', amount: -45750, date: 'in 28 days' },
];

// --- Main Component --- //
export default function CashflowPrototype() {
  const [currentScreen, setCurrentScreen] = useState('forecasting');
  const [scenarioComplete, setScenarioComplete] = useState(false);

  const NavItem = ({ icon, label, screen, active }) => (
    <button
      onClick={() => setCurrentScreen(screen)}
      className={`flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-md transition-all duration-200 ${active ? 'bg-blue-100 text-blue-700' : 'text-gray-600 hover:bg-gray-100'}`}>
      {icon}
      <span className="ml-3">{label}</span>
    </button>
  );

  const Sidebar = () => (
    <div className="w-64 bg-white border-r border-gray-200 flex flex-col">
      <div className="h-16 flex items-center px-6 border-b border-gray-200">
        <h1 className="text-xl font-bold text-[#1a365d]">Financly</h1>
      </div>
      <nav className="flex-1 p-4 space-y-2">
        <NavItem icon={<Home size={20} />} label="Dashboard" screen="forecasting" active={currentScreen === 'forecasting'} />
        <NavItem icon={<BarChart2 size={20} />} label="Cash Flow" screen="forecasting" active={['alertDetail', 'scenarioModeling', 'scenarioResult'].includes(currentScreen)} />
        <NavItem icon={<FileText size={20} />} label="Reports" screen="reports" active={currentScreen === 'reports'} />
        <NavItem icon={<DollarSign size={20} />} label="Transactions" screen="transactions" active={currentScreen === 'transactions'} />
        <NavItem icon={<Users size={20} />} label="Customers & Suppliers" screen="customers" active={currentScreen === 'customers'} />
      </nav>
      <div className="p-4 border-t border-gray-200">
        <NavItem icon={<Settings size={20} />} label="Settings & Integrations" screen="settings" active={currentScreen === 'settings'} />
      </div>
    </div>
  );

  const Header = () => (
    <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6">
      <h2 className="text-2xl font-bold text-gray-800">
        {currentScreen === 'forecasting' && 'Cash Flow Forecast'}
        {currentScreen === 'alertDetail' && 'Shortfall Analysis'}
        {currentScreen === 'scenarioModeling' && 'Run a New Scenario'}
        {currentScreen === 'scenarioResult' && 'Scenario Result'}
        {['reports', 'transactions', 'customers', 'settings'].includes(currentScreen) && `${currentScreen.charAt(0).toUpperCase() + currentScreen.slice(1)}`}
      </h2>
      <div className="flex items-center">
        <div className="flex items-center space-x-3">
          <img className="h-9 w-9 rounded-full object-cover" src="https://i.pravatar.cc/150?u=aishakhan" alt="Aisha Khan" />
          <div>
            <p className="text-sm font-medium text-gray-800">Aisha Khan</p>
            <p className="text-xs text-gray-500">Urban Bloom Retail</p>
          </div>
          <ChevronDown size={16} className="text-gray-500" />
        </div>
      </div>
    </header>
  );

  const CashChart = ({ data, highlightShortfall }) => {
    const maxBalance = Math.max(...data.map(d => d.balance));
    return (
      <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
        <div className="flex justify-between items-baseline">
            <h3 className="text-lg font-semibold text-gray-800">90-Day Cash Projection</h3>
            <p className="text-sm text-gray-500">Last updated: 2 mins ago</p>
        </div>
        <div className="mt-6 h-64 flex items-end space-x-2">
          {data.map((item, index) => {
            const barHeight = Math.max((item.balance / maxBalance) * 100, 0);
            const isShortfall = highlightShortfall && item.shortfall;
            return (
              <div key={index} className="flex-1 flex flex-col items-center group">
                <div className={`w-full rounded-t-md transition-all duration-300 ${isShortfall ? 'bg-red-500' : 'bg-blue-500'}`} style={{ height: `${barHeight}%` }}></div>
                <div className={`h-1 w-full ${isShortfall ? 'bg-red-800' : 'bg-blue-800'}`}></div>
                <p className="text-xs text-gray-500 mt-2 text-center">{item.week}</p>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  const ForecastingScreen = () => (
    <div className="space-y-6">
      {!scenarioComplete && (
        <div onClick={() => setCurrentScreen('alertDetail')} className="p-4 bg-red-100 border-l-4 border-red-500 rounded-r-lg flex items-center justify-between cursor-pointer hover:shadow-md transition-shadow">
          <div className="flex items-center">
            <AlertTriangle className="h-6 w-6 text-red-700 mr-3" />
            <div>
              <h3 className="font-semibold text-red-800">Potential Cash Shortfall Alert</h3>
              <p className="text-sm text-red-700">Our forecast predicts a cash balance of -$15,400 in 5 weeks. Review details to take action.</p>
            </div>
          </div>
          <button className="text-sm font-semibold text-red-800 hover:text-red-900">View Details &rarr;</button>
        </div>
      )}
      {scenarioComplete && (
         <div className="p-4 bg-green-100 border-l-4 border-green-500 rounded-r-lg flex items-center">
            <CheckCircle2 className="h-6 w-6 text-green-700 mr-3" />
            <div>
              <h3 className="font-semibold text-green-800">Shortfall Averted</h3>
              <p className="text-sm text-green-700">Your recent scenario has successfully resolved the projected cash shortfall. Your forecast is updated.</p>
            </div>
        </div>
      )}
      <CashChart data={scenarioComplete ? forecastData.resolved : forecastData.initial} highlightShortfall={!scenarioComplete} />
    </div>
  );

  const AlertDetailScreen = () => (
    <div className="space-y-6">
        <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
            <h3 className="text-lg font-semibold text-gray-800">Shortfall Breakdown: Week 5 (Projected -$15,400)</h3>
            <p className="text-sm text-gray-500 mt-1">The following key transactions are contributing to the projected shortfall. Our AI model has 92% confidence in this forecast.</p>
        </div>
        <div className="bg-white rounded-lg border border-gray-200 shadow-sm overflow-hidden">
            <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                    <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Type</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Description</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Due</th>
                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Amount (AUD)</th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                    {shortfallDetails.map((item, i) => (
                        <tr key={i}>
                            <td className="px-6 py-4 whitespace-nowrap text-sm">
                                <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${item.type.includes('Outgoing') ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>{item.type}</span>
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-800 font-medium">{item.description}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{item.date}</td>
                            <td className={`px-6 py-4 whitespace-nowrap text-sm text-right font-mono ${item.amount < 0 ? 'text-red-600' : 'text-green-600'}`}>{item.amount.toLocaleString('en-AU', { style: 'currency', currency: 'AUD' })}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
        <div className="p-4 bg-blue-100 border-l-4 border-blue-500 rounded-r-lg flex items-center justify-between">
          <div className="flex items-center">
            <Lightbulb className="h-6 w-6 text-blue-700 mr-3" />
            <div>
              <h3 className="font-semibold text-blue-800">Recommendation</h3>
              <p className="text-sm text-blue-700">Consider drawing down on your existing credit line or delaying a non-critical supplier payment to cover the gap.</p>
            </div>
          </div>
          <button onClick={() => setCurrentScreen('scenarioModeling')} className="bg-blue-600 text-white px-4 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 transition-colors">Model a Scenario</button>
        </div>
    </div>
  );

  const ScenarioModelingScreen = () => (
    <div className="max-w-2xl mx-auto bg-white p-8 rounded-lg border border-gray-200 shadow-sm">
        <h3 className="text-xl font-semibold text-gray-800">Model a Scenario to Resolve Shortfall</h3>
        <p className="text-sm text-gray-500 mt-1">Select an action to see its impact on your cash flow forecast.</p>
        <div className="mt-6 space-y-6">
            <div className="space-y-3">
                <label className="text-base font-medium text-gray-900">Recommended Actions</label>
                <fieldset className="mt-4">
                    <div className="space-y-4">
                        <div className="flex items-center">
                            <input id="credit-line" name="scenario-action" type="radio" defaultChecked className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300" />
                            <label htmlFor="credit-line" className="ml-3 block text-sm font-medium text-gray-700">Draw from NAB Business Line of Credit</label>
                        </div>
                        <div className="flex items-center">
                            <input id="delay-payment" name="scenario-action" type="radio" className="focus:ring-blue-500 h-4 w-4 text-blue-600 border-gray-300" />
                            <label htmlFor="delay-payment" className="ml-3 block text-sm font-medium text-gray-700">Delay supplier payment to 'Global Logistics' by 14 days</label>
                        </div>
                    </div>
                </fieldset>
            </div>
            <div>
                <label htmlFor="amount" className="block text-sm font-medium text-gray-700">Amount (AUD)</label>
                <div className="mt-1 relative rounded-md shadow-sm">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <span className="text-gray-500 sm:text-sm">$</span>
                    </div>
                    <input type="text" name="amount" id="amount" className="focus:ring-blue-500 focus:border-blue-500 block w-full pl-7 pr-12 sm:text-sm border-gray-300 rounded-md" placeholder="50,000.00" defaultValue="50,000.00" />
                </div>
            </div>
            <div className="flex justify-end pt-4">
                 <button onClick={() => setCurrentScreen('alertDetail')} className="bg-white py-2 px-4 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">Cancel</button>
                <button onClick={() => setCurrentScreen('scenarioResult')} className="ml-3 inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">Run Scenario & Update Forecast</button>
            </div>
        </div>
    </div>
  );

  const ScenarioResultScreen = () => {
    if (!scenarioComplete) setScenarioComplete(true);
    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm text-center">
                <CheckCircle2 className="h-12 w-12 text-green-500 mx-auto" />
                <h3 className="text-xl mt-4 font-semibold text-gray-800">Scenario Successful!</h3>
                <p className="text-sm text-gray-500 mt-1 max-w-xl mx-auto">Drawing down $50,000 from your credit line has resolved the projected shortfall. Your forecast has been updated to reflect this change.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-red-50 p-4 rounded-lg border border-red-200">
                    <h4 className="font-semibold text-red-800">Before Scenario</h4>
                    <p className="text-sm text-red-600 mt-1">Projected lowest balance: <span className="font-bold">-$15,400</span></p>
                </div>
                <div className="bg-green-50 p-4 rounded-lg border border-green-200">
                    <h4 className="font-semibold text-green-800">After Scenario</h4>
                    <p className="text-sm text-green-600 mt-1">New projected lowest balance: <span className="font-bold">$34,600</span></p>
                </div>
            </div>
            <CashChart data={forecastData.resolved} highlightShortfall={false} />
            <div className="flex justify-center">
                <button onClick={() => setCurrentScreen('forecasting')} className="bg-blue-600 text-white px-6 py-2 rounded-md text-sm font-semibold hover:bg-blue-700 transition-colors">Return to Dashboard</button>
            </div>
        </div>
    );
  }

  const PlaceholderScreen = ({ title }) => (
    <div className="bg-white p-8 rounded-lg border border-gray-200 shadow-sm text-center">
      <h2 className="text-xl font-semibold text-gray-700">{title}</h2>
      <p className="mt-2 text-gray-500">This screen is a placeholder for the prototype.</p>
    </div>
  );

  return (
    <div className="flex h-screen bg-gray-100 font-sans antialiased text-gray-900">
      <Sidebar />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header />
        <main className="flex-1 overflow-x-hidden overflow-y-auto">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-8">
            {currentScreen === 'forecasting' && <ForecastingScreen />}
            {currentScreen === 'alertDetail' && <AlertDetailScreen />}
            {currentScreen === 'scenarioModeling' && <ScenarioModelingScreen />}
            {currentScreen === 'scenarioResult' && <ScenarioResultScreen />}
            {currentScreen === 'reports' && <PlaceholderScreen title="Reports" />}
            {currentScreen === 'transactions' && <PlaceholderScreen title="Transactions" />}
            {currentScreen === 'customers' && <PlaceholderScreen title="Customers & Suppliers" />}
            {currentScreen === 'settings' && <PlaceholderScreen title="Settings & Integrations" />}
          </div>
        </main>
      </div>
    </div>
  );
}

